func counter() func() int {
    count := 0
    return func() int {
        count++
        return count
    }
}

func main() {
    next := counter()
    fmt.Println(next())
    fmt.Println(next())
    fmt.Println(next())
}

func tally(label string) func() {
    count := 0
    return func() {
        count++
        fmt.Println(label, count)
    }
}

func wallet() (func(int), func() int) {
    balance := 0
    deposit := func(amount int) {
        balance += amount
    }
    total := func() int { return balance }
    return deposit, total
}

func main() {
    deposit, total := wallet()
    deposit(30)
    deposit(20)
    fmt.Println(total())
}

func logged(f func(int) int) func(int) int {
    calls := 0
    return func(n int) int {
        calls++
        fmt.Println("call", calls)
        return f(n)
    }
}

func main() {
    double := logged(func(n int) int {
        return n * 2
    })
    fmt.Println(double(4))
    fmt.Println(double(5))
}

